                </P>","sha256":"cd4c2d52198f0f12d56b0c89e7d83f46678dfad72c825cc1fbe529d89e6d4528","document":{"url":"https://www.govinfo.gov/content/pkg/CFR-2026-title14-vol2/xml/CFR-2026-title14-vol2-part107.xml","sha256":"0c07b393796351d4a6b2fef98b330d16d1318d79a5b2bb608894a93443eed70f","readPath":"/v1/rule-sources/govinfo.cfr.2026.title14.vol2.part107/content","sourceId":"govinfo.cfr.2026.title14.vol2.part107","byteLength":86803,"contentType":"application/xml; charset=utf-8"},"encoding":"utf-8","textSpan":{"end":26770,"unit":"utf8_byte","start":26002,"sourceId":"govinfo.cfr.2026.title14.vol2.part107"},"reference":"14 CFR 107.31(a) (edition of 2026-01-01)","byteLength":768},"target":{"subjectKind":"flight"},"adopted":false,"section":"107.31","version":1,"wording":{"pass":"The flight is planned within visual line of sight. Whether the persons the paragraph names could see the aircraft throughout the flight is for a person to review."},"coverage":"automated","paragraph":"§ 107.31(a)","population":{"of":"in_adoption_dates"},"applicability":[],"adoptionParameters":[]},{"id":"ledger.part107.107.36","check":{"kind":"value.one-of","params":{"field":"values.record.hazardousMaterial","expected":["not_hazardous"]},"version":1,"definitionDigest":"cabc03bd68f9cfea4c63827586dd87f1a7b4fe5a8abad2694ff2a1b6fbc9e61f"},"reads":[{"name":"subject","type":"operator.record","about":"target","plans":true,"where":[{"field":"values.recordType","oneOf":["aircraft.payload"]},{"field":"values.recordVersion","oneOf":[1]}],"onFile":"payload declaration","select":"latest","required":true,"versions":[1]}],"title":"Payload recorded as not hazardous material","digest":"c195eb1ecd1075a9dd8f1f5ec7b565ef5fd47c91fab83b142eeee9ee3c3bcd0b","review":"ai_drafted","source":{"kind":"regulation","text":"<P>A small unmanned aircraft may not carry hazardous material. For purposes of this section, the term hazardous material is defined in 49 CFR 171.8.</P>","sha256":"e7a9589b4e1aae62d95717e1d384e522ceed22cd5916