:277},"target":{"subjectKind":"aircraft"},"adopted":false,"section":"107.15","version":1,"wording":{"pass":"The latest condition recorded for the aircraft is that no unsafe condition is known. Whether the remote pilot in command checked it before this flight is for a person to review."},"coverage":"automated","paragraph":"§ 107.15(a)","population":{"of":"on_record"},"applicability":[],"adoptionParameters":[]},{"id":"ledger.part107.107.15.b","title":"Flight not continued once the aircraft is no longer in a condition for safe operation","digest":"7d2fe036670a3f1e9928dd405d43decd0694cb5329336825f8f12933564c9ddc","review":"ai_drafted","source":{"kind":"regulation","text":"<P>(b) No person may continue flight of the small unmanned aircraft when he or she knows or has reason to know that the small unmanned aircraft system is no longer in a condition for safe operation.</P>","sha256":"64be66aa691188b8cba3c9604d006627dc9f9d1e9301cef872e926c43b36ddbf","document":{"url":"https://www.govinfo.gov/content/pkg/CFR-2026-title14-vol2/xml/CFR-2026-title14-vol2-part107.xml","sha256":"0c07b393796351d4a6b2fef98b330d16d1318d79a5b2bb608894a93443eed70f","readPath":"/v1/rule-sources/govinfo.cfr.2026.title14.vol2.part107/content","sourceId":"govinfo.cfr.2026.title14.vol2.part107","byteLength":86803,"contentType":"application/xml; charset=utf-8"},"encoding":"utf-8","textSpan":{"end":19629,"unit":"utf8_byte","start":19427,"sourceId":"govinfo.cfr.2026.title14.vol2.part107"},"reference":"14 CFR 107.15(b) (edition of 2026-01-01)","byteLength":202},"adopted":false,"section":"107.15","version":1,"coverage":"manual","paragraph":"§ 107.15(b)","dependencies":[]},{"id":"ledger.part107.107.17","check":{"kind":"value.one-of","params":{"field":"values.record.medicalStatement","expected":["no_known_condition"]},"version":1,"definitionDigest":"cabc03bd68f9cfea4c63827586dd87f1a7b4fe5a8abad2694ff2a1b6fbc9e61f"},"reads":[{"name":"subject","type":"operator.record","about":"target","where":[{"field":"values.rec